import { SignagePlaylistSchedule } from './interfaces';
import { MediaAnimation, SignageMedia } from './media.class';

export class SignagePlaylistMedia {
    public readonly id: string;
    public readonly playlist_id: string;
    public readonly items: string[];
    public readonly media: SignageMedia[];
    public readonly schedules: SignagePlaylistItemSchedule[];
    public readonly created_at: number;
    public readonly updated_at: number;

    public readonly user_id: string;
    public readonly user_name: string;
    public readonly user_email: string;

    public readonly approved: boolean;
    public readonly approval_requested: boolean;
    public readonly requested_by_id: string;
    public readonly approved_by_id: string;
    public readonly approved_by_email: string;
    public readonly approved_by_name: string;
    public readonly shared_with: { id: string, name: string }[];

    constructor(data: Partial<SignagePlaylistMedia> = {}) {
        this.id = data.id || '';
        this.playlist_id = data.playlist_id || '';
        this.created_at = data.created_at || 0;
        this.updated_at = data.updated_at || 0;

        this.items = data.items || [];
        this.media = data.media || [];
        this.schedules = data.schedules || [];

        this.approved = !!data.approved;
        this.approval_requested = !!data.approval_requested;
        this.requested_by_id = data.requested_by_id || '';
        this.approved_by_id = data.approved_by_id || '';
        this.approved_by_email = data.approved_by_email || '';
        this.approved_by_name = data.approved_by_name || '';

        this.user_id = data.user_id || '';
        this.user_name = data.user_name || '';
        this.user_email = data.user_email || '';
        this.shared_with = data.shared_with || [];
    }
}

export class SignagePlaylistItemSchedule {
    public readonly id: string;
    public readonly playlist_id: string;
    public readonly item_id: string;
    public readonly schedules: SignagePlaylistSchedule[];
    public readonly created_at: number;
    public readonly updated_at: number;
    public readonly media: SignageMedia;

    constructor(data: Partial<SignagePlaylistItemSchedule> = {}) {
        this.id = data.id || '';
        this.playlist_id = data.playlist_id || '';
        this.item_id = data.item_id || '';
        this.schedules = data.schedules || [];
        this.created_at = data.created_at || 0;
        this.updated_at = data.updated_at || 0;
        this.media = data.media || new SignageMedia({});
    }
}

export class SignagePlaylist {
    public readonly id: string;
    public readonly created_at: number;
    public readonly updated_at: number;
    public readonly name: string;
    public readonly description: string;
    public readonly authority_id: string;
    public readonly orientation: string;
    public readonly play_count: number;
    public readonly play_through_count: number;
    public readonly default_animation: MediaAnimation;
    public readonly random: boolean;
    public readonly enabled: boolean;
    public readonly distribution: boolean;
    public readonly default_duration: number;
    public readonly schedules: SignagePlaylistSchedule[];
    public readonly valid_from?: number;
    public readonly valid_until?: number;
    public readonly shared_with: { id: string, name: string }[];

    constructor(data: Partial<SignagePlaylist>) {
        this.id = data.id || '';
        this.created_at = data.created_at || 0;
        this.updated_at = data.updated_at || 0;
        this.name = data.name || '';
        this.description = data.description || '';
        this.authority_id = data.authority_id || '';
        this.orientation = data.orientation || '';
        this.play_count = data.play_count || 0;
        this.play_through_count = data.play_through_count || 0;
        this.default_animation = data.default_animation || MediaAnimation.Cut;
        this.random = data.random || false;
        this.enabled = data.enabled ?? true;
        this.distribution = data.distribution || false;
        this.default_duration = data.default_duration ?? 15 * 1000;
        this.valid_from = data.valid_from;
        this.valid_until = data.valid_until;
        this.schedules = data.schedules || [];
        this.shared_with = data.shared_with || [];
    }
}
